let _confirmResolve = null;
function customConfirm(message){
  return new Promise(resolve=>{
    _confirmResolve = resolve;
    document.getElementById('confirmOverlay').innerHTML = `
      <div class="overlay" style="z-index:80;">
        <div class="day-menu" style="text-align:center;">
          <div class="dm-date" style="white-space:pre-line;">${message}</div>
          <button class="menu-btn" onclick="_confirmAnswer(true)">はい</button>
          <button class="menu-btn cancel" onclick="_confirmAnswer(false)">いいえ</button>
        </div>
      </div>`;
  });
}
window._confirmAnswer = function(val){
  document.getElementById('confirmOverlay').innerHTML = '';
  const r = _confirmResolve;
  _confirmResolve = null;
  if(r) r(val);
};

function customAlert(message){
  return new Promise(resolve=>{
    document.getElementById('confirmOverlay').innerHTML = `
      <div class="overlay" style="z-index:80;">
        <div class="day-menu" style="text-align:center;">
          <div class="dm-date" style="white-space:pre-line;">${message}</div>
          <button class="menu-btn" onclick="_alertAnswer()">OK</button>
        </div>
      </div>`;
    window._alertResolve = resolve;
  });
}
window._alertAnswer = function(){
  document.getElementById('confirmOverlay').innerHTML = '';
  const r = window._alertResolve;
  window._alertResolve = null;
  if(r) r();
};

function toDateStr(d){
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function parseDate(s){
  const [y,m,d] = s.split('-').map(Number);
  return new Date(y,m-1,d);
}
function daysBetween(a,b){
  return Math.round((parseDate(b) - parseDate(a)) / 86400000);
}
function addDays(dateStr, n){
  const d = parseDate(dateStr);
  d.setDate(d.getDate()+n);
  return toDateStr(d);
}
function fmtShort(dateStr){
  const d = parseDate(dateStr);
  return (d.getMonth()+1)+'/'+d.getDate();
}
function fmtYMD(dateStr){
  const d = parseDate(dateStr);
  return d.getFullYear()+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0');
}
function uid(){
  return 'r'+Date.now()+Math.floor(Math.random()*1000);
}

// ---- 年・月・日プルダウン共通ヘルパー ----
function ymdYearOptions(selectedY){
  const thisYear = new Date().getFullYear();
  let html = `<option value=""${selectedY?'':' selected'}>-</option>`;
  for(let y=thisYear-8; y<=thisYear+1; y++){
    html += `<option value="${y}"${y===selectedY?' selected':''}>${y}</option>`;
  }
  return html;
}
function ymdMonthOptions(selectedM){
  let html = `<option value=""${selectedM?'':' selected'}>-</option>`;
  for(let mo=1; mo<=12; mo++){
    html += `<option value="${mo}"${mo===selectedM?' selected':''}>${mo}</option>`;
  }
  return html;
}
function ymdDayOptions(selectedD, y, mo){
  const maxDay = (y && mo) ? new Date(y, mo, 0).getDate() : 31;
  const d = (selectedD && selectedD <= maxDay) ? selectedD : (selectedD ? maxDay : null);
  let html = `<option value=""${d?'':' selected'}>-</option>`;
  for(let day=1; day<=maxDay; day++){
    html += `<option value="${day}"${day===d?' selected':''}>${day}</option>`;
  }
  return html;
}
function renderYMDRow(prefix, dateStr, changeFnName){
  const [y, mo, d] = dateStr ? dateStr.split('-').map(Number) : [null,null,null];
  return `
    <div class="ym-row">
      <select id="${prefix}Year" onchange="${changeFnName}()">${ymdYearOptions(y)}</select><span>年</span>
      <select id="${prefix}Month" onchange="${changeFnName}()">${ymdMonthOptions(mo)}</select><span>月</span>
      <select id="${prefix}Day" onchange="${changeFnName}()">${ymdDayOptions(d,y,mo)}</select><span>日</span>
    </div>`;
}
function readYMDRow(prefix){
  const yEl = document.getElementById(prefix+'Year');
  const mEl = document.getElementById(prefix+'Month');
  const dEl = document.getElementById(prefix+'Day');
  if(!yEl || !mEl || !dEl) return '';
  const y = yEl.value, mo = mEl.value, d = dEl.value;
  if(!y || !mo || !d) return '';
  return `${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
}
function refreshYMDDayOptions(prefix){
  const yEl = document.getElementById(prefix+'Year');
  const mEl = document.getElementById(prefix+'Month');
  const dEl = document.getElementById(prefix+'Day');
  if(!yEl || !mEl || !dEl) return;
  const y = Number(yEl.value) || null;
  const mo = Number(mEl.value) || null;
  const curD = Number(dEl.value) || null;
  dEl.innerHTML = ymdDayOptions(curD, y, mo);
}

async function loadData(){
  try{
    const raw = localStorage.getItem(STORAGE_KEY);
    records = raw ? JSON.parse(raw) : [];
  }catch(e){
    records = [];
  }
  records.sort((a,b)=> a.start < b.start ? -1 : 1);
  try{
    const raw2 = localStorage.getItem(NOTES_KEY);
    dailyNotes = raw2 ? JSON.parse(raw2) : {};
  }catch(e){
    dailyNotes = {};
  }
  quickNoteOpen = false;
  render();
}

async function saveData(){
  records.sort((a,b)=> a.start < b.start ? -1 : 1);
  try{
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  }catch(e){
    console.error('保存に失敗しました', e);
  }
}

async function saveNotes(){
  try{
    localStorage.setItem(NOTES_KEY, JSON.stringify(dailyNotes));
  }catch(e){
    console.error('保存に失敗しました', e);
  }
}

function computeStats(){
  const cycleLens = [];
  for(let i=1;i<records.length;i++){
    const len = daysBetween(records[i-1].start, records[i].start);
    if(len>0 && len<90) cycleLens.push(len);
  }
  const recentCycles = cycleLens.slice(-6);
  const avgCycle = recentCycles.length
    ? Math.round(recentCycles.reduce((a,b)=>a+b,0)/recentCycles.length)
    : 28;

  const periodLens = records
    .filter(r=>r.end)
    .map(r=> daysBetween(r.start, r.end)+1)
    .filter(n=> n>0 && n<15);
  const recentPeriods = periodLens.slice(-6);
  const avgPeriod = recentPeriods.length
    ? Math.round(recentPeriods.reduce((a,b)=>a+b,0)/recentPeriods.length)
    : 5;

  const last = records.length ? records[records.length-1] : null;
  let predictNext = null, predictOvulation = null, fertileStart=null, fertileEnd=null;
  if(last){
    predictNext = addDays(last.start, avgCycle);
    predictOvulation = addDays(predictNext, -14);
    fertileStart = addDays(predictOvulation, -5);
    fertileEnd = addDays(predictOvulation, 1);
  }

  const todayStr = toDateStr(new Date());
  let cycleDay = null;
  if(last){
    const d = daysBetween(last.start, todayStr) + 1;
    if(d >= 1) cycleDay = d;
  }

  return {avgCycle, avgPeriod, last, predictNext, predictOvulation, fertileStart, fertileEnd, cycleDay};
}

function getPhase(stats){
  const {cycleDay, avgCycle, avgPeriod, last} = stats;
  if(!last || cycleDay===null){
    return {key:'none', label:'記録をはじめましょう', desc:'まずは直近の生理開始日を記録してね', progress:0.15};
  }
  const ovulationDay = avgCycle - 14;
  if(cycleDay <= avgPeriod){
    return {key:'period', label:'月経期', desc:'からだを休める時期。無理せずゆっくりね', progress:0.15};
  }else if(cycleDay < ovulationDay - 1){
    const p = (cycleDay - avgPeriod) / Math.max(1,(ovulationDay - avgPeriod));
    return {key:'follicular', label:'卵胞期', desc:'心身ともに調子が上向きやすい時期', progress: 0.3 + p*0.4};
  }else if(cycleDay <= ovulationDay + 1){
    return {key:'ovulation', label:'排卵期', desc:'もっとも体調が整いやすいピークの時期', progress:1};
  }else{
    const p = (cycleDay - (ovulationDay+1)) / Math.max(1,(avgCycle - (ovulationDay+1)));
    return {key:'luteal', label:'黄体期', desc:'むくみや眠気を感じやすい時期。労わって', progress: 0.85 - Math.min(0.55,p*0.55)};
  }
}

function renderFlower(phase){
  const useMoon = phase.key === 'none' || phase.key === 'luteal';
  const img = useMoon ? BUNNY_MOON_IMG : BUNNY_STAR_IMG;
  const alt = useMoon ? 'お月さまとうさぎ' : 'お星さまとうさぎ';
  return `<div class="flower-stage"><img src="${img}" alt="${alt}" style="width:100%;height:100%;object-fit:contain;"></div>`;
}

const BLOOD_BG_COLORS = {0:'#F8C4D4', 1:'#F193A9', 2:'#E4587A', 3:'#C62148', 4:'#B01D3F'};

function noteMarkers(dateStr){
  const note = dailyNotes[dateStr];
  if(!note) return '';
  let m = '';
  if(note.symptoms && note.symptoms.length) m += '<span class="mark-symptom"></span>';
  if(note.heart === 'あり') m += '<span class="mark-heart">❤️</span>';
  if(note.heart === 'なし') m += '<span class="mark-heart">💙</span>';
  if(note.weight || note.temperature) m += '<span class="mark-other"></span>';
  return m;
}

function renderCalendar(stats){
  const y = viewMonth.getFullYear();
  const m = viewMonth.getMonth();
  const first = new Date(y,m,1);
  const startWeekday = first.getDay();
  const daysInMonth = new Date(y,m+1,0).getDate();
  const todayStr = toDateStr(new Date());

  function classify(dateStr){
    for(const r of records){
      if(r.end){
        if(dateStr >= r.start && dateStr <= r.end) return 'period';
      }else{
        if(dateStr === r.start) return 'period';
      }
    }
    if(stats.predictNext){
      const predEnd = addDays(stats.predictNext, stats.avgPeriod-1);
      if(dateStr >= stats.predictNext && dateStr <= predEnd) return 'predicted';
    }
    // その日が属する周期（過去 or 直近）を見つけて、その周期なりの妊娠しやすい時期を計算する
    const sorted = [...records].sort((a,b)=> a.start < b.start ? -1 : 1);
    for(let i=0;i<sorted.length;i++){
      const A = sorted[i];
      const nextStart = sorted[i+1] ? sorted[i+1].start : stats.predictNext;
      if(!nextStart) continue;
      if(dateStr >= A.start && dateStr < nextStart){
        const ovulation = addDays(nextStart, -14);
        const peakStart = addDays(ovulation, -1);
        const peakEnd = addDays(ovulation, 1);
        const midStart = addDays(ovulation, -5);
        const midEnd = addDays(ovulation, 1);
        if(dateStr >= peakStart && dateStr <= peakEnd) return 'fertile-peak';
        if(dateStr >= midStart && dateStr <= midEnd) return 'fertile-mid';
        return '';
      }
    }
    return '';
  }

  let cells = '';
  ['日','月','火','水','木','金','土'].forEach(w=> cells += `<div class="wd">${w}</div>`);
  for(let i=0;i<startWeekday;i++) cells += `<div class="cal-cell empty"></div>`;
  for(let d=1; d<=daysInMonth; d++){
    const dateStr = toDateStr(new Date(y,m,d));
    const cls = classify(dateStr);
    const todayClass = dateStr===todayStr ? ' today' : '';
    const noteDot = noteMarkers(dateStr);
    let periodStyle = '';
    if(cls === 'period'){
      const bloodLv = (dailyNotes[dateStr] && dailyNotes[dateStr].blood) || 0;
      periodStyle = ` style="background:${BLOOD_BG_COLORS[bloodLv]};"`;
    }
    cells += `<div class="cal-cell ${cls}"${periodStyle} onclick="openDayMenu('${dateStr}')">
      <span class="cal-daynum${todayClass}">${d}</span>
      <span class="cal-marks">${noteDot}</span>
    </div>`;
  }

  const monthLabel = `${y}年 ${m+1}月`;
  return `
  <div class="card">
    <div class="cal-head">
      <button class="cal-nav" onclick="changeMonth(-1)">‹</button>
      <div class="month">${monthLabel}</div>
      <button class="cal-nav" onclick="changeMonth(1)">›</button>
    </div>
    <div class="cal-grid">${cells}</div>
    <div class="legend">
      <span><span class="dot pink"></span>生理日</span>
      <span><span class="dot pinkline"></span>次回予測</span>
    </div>
    <div class="legend">
      <span><span class="dot sagedash"></span>妊娠しやすい(中)</span>
      <span><span class="dot sageline"></span>妊娠しやすい(高)</span>
    </div>
    <div class="legend">
      <span><span class="dot" style="background:#C62148;"></span>血量</span>
      <span><span class="dot" style="background:var(--sage);"></span>症状</span>
      <span>❤️・💙</span>
      <span><span class="dot" style="background:#E8935A;"></span>体重・体温</span>
    </div>
  </div>`;
}

function accordionCard(title, bodyHtml, isOpen, toggleFnName){
  return `<div class="card">
    <button class="accordion-header" onclick="${toggleFnName}()">
      <span>${title}</span>
      <span class="accordion-arrow">${isOpen ? '▲' : '▼'}</span>
    </button>
    ${isOpen ? bodyHtml : ''}
  </div>`;
}

function renderHistory(){
  if(records.length===0) return '';
  const rev = [...records].reverse();
  const visible = rev.slice(0, historyVisibleCount);
  const BAR_SCALE = 40; // バーの基準日数（この日数で満タン）
  let html = '';
  visible.forEach((r, idx)=>{
    const origIdx = records.length - 1 - idx;
    let cycleLen = null;
    if(origIdx > 0){
      cycleLen = daysBetween(records[origIdx-1].start, r.start);
    }
    const dateRange = r.end ? `${fmtYMD(r.start)} 〜 ${fmtShort(r.end)}` : `${fmtYMD(r.start)} 〜`;
    const periodDays = r.end ? (daysBetween(r.start,r.end)+1) : null;
    const lenNote = r.end ? `${periodDays}日間` : '継続中';

    let barHtml = '';
    if(periodDays){
      const periodPct = Math.min(100, (periodDays/BAR_SCALE)*100);
      const cycleMarker = cycleLen
        ? `<span class="bar-cyclenum" style="left:${Math.min(94,(cycleLen/BAR_SCALE)*100)}%">${cycleLen}</span>`
        : '';
      barHtml = `
        <div class="bar-track">
          <div class="bar-fill" style="width:${periodPct}%">${periodDays}</div>
          ${cycleMarker}
        </div>`;
    }

    html += `
    <div class="history-item-block">
      <div class="history-item">
        <div>
          <div class="hist-date">${dateRange}</div>
          <div class="hist-sub">${lenNote}${r.note? ' ・ '+r.note : ''}</div>
        </div>
        <div style="display:flex;align-items:center;">
          <button class="del-btn" onclick="startEdit('${r.id}')" title="編集する">✎</button>
          <button class="del-btn" onclick="deleteRecord('${r.id}')" title="削除する">✕</button>
        </div>
      </div>
      ${barHtml}
    </div>`;
  });
  if(historyVisibleCount > 10){
    html += `<button class="btn ghost" onclick="collapseHistory()">▲ 閉じる（10件表示に戻す）</button>`;
  }
  if(rev.length > historyVisibleCount){
    html += `<button class="btn ghost" onclick="loadMoreHistory()">▼ もっと見る</button>`;
  }
  return accordionCard('記録一覧', html, showHistory, 'toggleHistory');
}

function renderWeightList(){
  const hasVal = v => v !== null && v !== undefined && v !== '';
  const entries = Object.keys(dailyNotes)
    .filter(d => hasVal(dailyNotes[d].weight) || hasVal(dailyNotes[d].temperature))
    .sort((a,b)=> a < b ? 1 : -1);

  if(entries.length===0) return '';

  const visible = entries.slice(0, weightVisibleCount);
  let html = '';
  visible.forEach(d=>{
    const note = dailyNotes[d];
    const parts = [];
    if(hasVal(note.weight)) parts.push(`${note.weight}kg`);
    if(hasVal(note.temperature)) parts.push(`${note.temperature}℃`);
    html += `
    <div class="history-item-block">
      <div class="history-item" onclick="openNoteModal('${d}')" style="cursor:pointer;">
        <div class="hist-date">${fmtYMD(d)}</div>
        <div class="hist-cyclen" style="margin-right:0;">${parts.join('　')}</div>
      </div>
    </div>`;
  });
  if(weightVisibleCount > 10){
    html += `<button class="btn ghost" onclick="collapseWeightList()">▲ 閉じる（10件表示に戻す）</button>`;
  }
  if(entries.length > weightVisibleCount){
    html += `<button class="btn ghost" onclick="loadMoreWeightList()">▼ もっと見る</button>`;
  }
  return accordionCard('体重・体温の記録', html, showWeightList, 'toggleWeightList');
}

function renderDataManage(){
  const body = `
    <input type="file" id="restoreFileInput" accept="application/json,.json" style="display:none;" onchange="handleRestoreFile(event)">
    <button class="menu-btn sage" onclick="backupData()">📦 バックアップ保存</button>
    <button class="menu-btn sage" onclick="document.getElementById('restoreFileInput').click()">📥 バックアップ復元</button>
    <button class="menu-btn danger" onclick="deleteAllData()">🗑 全データを削除する</button>
  `;
  return accordionCard('データ管理', body, showDataManage, 'toggleDataManage');
}

function renderFuturePredictions(stats){
  if(!stats.last || !stats.predictNext) return '';
  const {avgCycle, avgPeriod} = stats;
  let cursorStart = stats.predictNext;
  let html = '';
  const COUNT = 6;
  for(let i=0; i<COUNT; i++){
    const end = addDays(cursorStart, avgPeriod-1);
    html += `
    <div class="history-item-block">
      <div class="history-item">
        <div>
          <div class="hist-date">${fmtYMD(cursorStart)} 〜 ${fmtShort(end)}</div>
          <div class="hist-sub">予測 ${avgPeriod}日間</div>
        </div>
        <span class="hist-cyclen">周期 ${avgCycle}日</span>
      </div>
    </div>`;
    cursorStart = addDays(cursorStart, avgCycle);
  }
  return accordionCard('生理予測', html, showFuturePredict, 'toggleFuturePredict');
}

