// ---- データ管理：バックアップ・復元・全削除 ----
window.backupData = function(){
  const payload = {
    app: 'ことりごよみ',
    exportedAt: new Date().toISOString(),
    records: records,
    dailyNotes: dailyNotes
  };
  const json = JSON.stringify(payload, null, 2);
  const blob = new Blob([json], {type: 'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const today = toDateStr(new Date()).replace(/-/g,'');
  a.href = url;
  a.download = `kotori-goyomi-backup-${today}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

window.handleRestoreFile = async function(event){
  const file = event.target.files[0];
  event.target.value = '';
  if(!file) return;

  let data;
  try{
    const text = await file.text();
    data = JSON.parse(text);
  }catch(e){
    await customAlert('このファイルは読み込めませんでした。\nバックアップ用のJSONファイルを選んでね。');
    return;
  }

  if(!data || !Array.isArray(data.records) || typeof data.dailyNotes !== 'object'){
    await customAlert('このファイルの中身が、ことりごよみのバックアップ形式と違うみたいです。');
    return;
  }

  const ok = await customConfirm(`バックアップを復元しますか？\n\n今のデータはすべて上書きされます。\n（記録 ${data.records.length}件 を読み込みます）`);
  if(!ok) return;

  records = data.records;
  dailyNotes = data.dailyNotes;
  await saveData();
  await saveNotes();
  render();
  await customAlert('復元が完了しました🌸');
};

window.deleteAllData = async function(){
  const ok1 = await customConfirm('本当に全てのデータを削除しますか？\nこの操作は元に戻せません。');
  if(!ok1) return;
  const ok2 = await customConfirm('もう一度確認します。\n生理の記録・体調メモ、すべて消えます。\n本当によろしいですか？');
  if(!ok2) return;
  records = [];
  dailyNotes = {};
  await saveData();
  await saveNotes();
  render();
};

